import java.util.*;
import java.io.*;

public class EdE {
    public static void main(String[] args) throws Exception {
        int num = 998244353;
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        long n = Long.parseLong(tokenizer.nextToken());
        long k = Long.parseLong(tokenizer.nextToken());

        long[] factorials = new long[200001];
        factorials[0] = 1;
        long factorialProduct = 1;
        for (int i = 1; i <= 200000; i++) {
            factorialProduct = (factorialProduct * i) % num;
            factorials[i] = factorialProduct;
        }

        long total = 0;
        for (int i = 0; i < n - k; i++) {
            long comb = factorials[(int)(n - k)];
            comb = (comb * power(factorials[i], num - 2, num)) % num;
            comb = (comb * power(factorials[(int)(n - k - i)], num - 2, num)) % num;
            long term = power(n - k - i, n, num);
            if (i % 2 == 0) {
                total = (total + comb * term) % num;
            } else {
                total = (total - comb * term) % num;
            }
        }
        if (k >= n) {
            writer.println(0);
        } else {
            if (k != 0) {
                total = (total * 2) % num;
            }
            total = (total * factorials[(int) n]) % num;
            total = (total * power(factorials[(int) k], num - 2, num)) % num;
            total = (total * power(factorials[(int) (n - k)], num - 2, num)) % num;
            total = (total + num) % num; // ensure non-negative
            writer.println(total);
        }
        writer.close();
    }

    public static int power(long base, long exp, long mod) {
        long result = 1;
        long b = base % mod;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return (int) result;
    }
}
